"use strict";(globalThis.webpackChunklinux_cleanup_docs||=[]).push([[8524],{63260(e){e.exports=JSON.parse('{"tag":{"label":"modes","permalink":"/fr/tags/modes","allTagsPath":"/fr/tags","count":17,"items":[{"id":"modes/scan","title":"Analyse (lecture seule)","description":"Examiner les racines de cache, les t\xe9l\xe9chargements partiels et les autres candidats au nettoyage sous Linux sans supprimer de fichiers.","permalink":"/fr/modes/scan"},{"id":"modes/overview","title":"Aper\xe7u des modes","description":"Tous les modes de linux-cleanup regroup\xe9s selon ce qu\u2019ils font\u202f: inspection en lecture seule, nettoyage guid\xe9 et par lot, modes interactifs pour les donn\xe9es personnelles, et outils de sortie et de r\xe9paration.","permalink":"/fr/modes/overview"},{"id":"modes/globals-audit","title":"Audit des paquets globaux","description":"Un audit en lecture seule des paquets install\xe9s globalement avec npm, pnpm, yarn, bun et deno, qui marque chacun comme utilis\xe9 r\xe9cemment, requis par un autre ou inutilis\xe9, et affiche des commandes de d\xe9sinstallation \xe0 lancer vous-m\xeame.","permalink":"/fr/modes/globals-audit"},{"id":"modes/home-audit","title":"Audit du dossier personnel","description":"Une liste en lecture seule des 20 plus grosses entr\xe9es de votre dossier personnel, que linux-cleanup puisse les nettoyer ou non\u202f: le moyen le plus rapide de savoir ce qui occupe vraiment le disque.","permalink":"/fr/modes/home-audit"},{"id":"modes/speed","title":"Diagnostic de vitesse","description":"Examiner la temp\xe9rature, la pression et les t\xe2ches de d\xe9marrage de Linux, puis d\xe9cider d\u2019appliquer ou non chaque changement propos\xe9.","permalink":"/fr/modes/speed"},{"id":"modes/doctor","title":"Doctor","description":"D\xe9tecter les environnements d\u2019ex\xe9cution install\xe9s sur le disque mais absents de l\u2019initialisation du shell (nvm, pnpm, bun, deno, cargo) et ajouter le bloc d\u2019initialisation standard apr\xe8s confirmation. Ajout uniquement.","permalink":"/fr/modes/doctor"},{"id":"modes/all-safe","title":"Enti\xe8rement s\xfbr (par lot)","description":"Nettoyer en une seule passe tous les caches r\xe9g\xe9n\xe9rables. Le mode con\xe7u pour cron et la maintenance sans surveillance, et le seul auquel --yes s\u2019applique.","permalink":"/fr/modes/all-safe"},{"id":"modes/editor-extensions","title":"Extensions d\u2019\xe9diteurs","description":"Supprimer les versions remplac\xe9es d\u2019extensions VS Code et Cursor (les anciennes copies laiss\xe9es apr\xe8s une mise \xe0 jour), sous r\xe9serve d\u2019une v\xe9rification de remplacement et du seuil d\u2019inactivit\xe9.","permalink":"/fr/modes/editor-extensions"},{"id":"modes/personal-stale-files","title":"Fichiers personnels inutilis\xe9s","description":"Le mode uniquement interactif qui trouve les gros fichiers inutilis\xe9s depuis longtemps dans ~/Downloads et les racines non prot\xe9g\xe9es configur\xe9es.","permalink":"/fr/modes/personal-stale-files"},{"id":"modes/menu","title":"Menu","description":"Le menu num\xe9rot\xe9 qui permet de lancer une seule cat\xe9gorie de linux-cleanup \xe0 la fois plut\xf4t que tout le parcours guid\xe9.","permalink":"/fr/modes/menu"},{"id":"modes/system-cleanup","title":"Nettoyage du syst\xe8me (sudo)","description":"Le mode syst\xe8me avec sudo\u202f: apt, journal, Snap, liste des noyaux, fichiers anciens de /tmp et vidage facultatif du cache de pages.","permalink":"/fr/modes/system-cleanup"},{"id":"modes/walkthrough","title":"Parcours guid\xe9 (par d\xe9faut)","description":"Le mode par d\xe9faut de linux-cleanup\u202f: dix \xe9tapes guid\xe9es \xe0 travers toutes les cat\xe9gories de nettoyage, avec une question avant chacune, un total cumul\xe9 et un rapport de session JSON.","permalink":"/fr/modes/walkthrough"},{"id":"modes/reports","title":"Rapports","description":"Le parcours guid\xe9 peut \xe9crire un enregistrement de session JSON. Listez, consultez, convertissez en Markdown ou HTML et exportez ces enregistrements.","permalink":"/fr/modes/reports"},{"id":"modes/node-modules-finder","title":"Recherche des node_modules d\xe9laiss\xe9s","description":"Trouver les dossiers node_modules de projets inutilis\xe9s depuis N jours ou plus et les supprimer en mode interactif. Souvent le plus gros gain d\u2019espace sur une machine de d\xe9veloppeur.","permalink":"/fr/modes/node-modules-finder"},{"id":"reference/modes-matrix","title":"Tableau des modes","description":"Tous les modes de linux-cleanup c\xf4te \xe0 c\xf4te\u202f: s\u2019ils suppriment, s\u2019ils sont interactifs, s\u2019ils utilisent sudo et s\u2019ils \xe9crivent un enregistrement de session.","permalink":"/fr/reference/modes-matrix"},{"id":"modes/partial-downloads","title":"T\xe9l\xe9chargements partiels ou orphelins","description":"Trouver et supprimer les fichiers de t\xe9l\xe9chargements partiels abandonn\xe9s (.crdownload, .part et .fdmdownload) laiss\xe9s par des transferts interrompus de navigateurs et de gestionnaires de t\xe9l\xe9chargement.","permalink":"/fr/modes/partial-downloads"},{"id":"modes/tui","title":"TUI (menu visuel)","description":"Le menu visuel pilot\xe9 par whiptail ou dialog, ajout\xe9 dans linux-cleanup 1.3.0, avec repli sur le menu de la CLI si aucun des deux n\u2019est install\xe9.","permalink":"/fr/modes/tui"}],"unlisted":false}}')}}]);